UNION ALL SELECT '<= ndv(partsupp.ps_partkey, partsupp.ps_suppkey | partsupp where exists["part".p_partkey = partsupp.ps_partkey](part where "part".p_name < ''foresu'' and "part".p_name >= ''forest''))' AS fact, (SELECT count(*) FROM (SELECT DISTINCT "partsupp.ps_partkey", "partsupp.ps_suppkey" FROM (SELECT * FROM (SELECT "ps_partkey" AS "partsupp.ps_partkey", "ps_suppkey" AS "partsupp.ps_suppkey", "ps_availqty" AS "partsupp.ps_availqty", "ps_supplycost" AS "partsupp.ps_supplycost", "ps_comment" AS "partsupp.ps_comment" FROM partsupp) AS "_t0" WHERE EXISTS (SELECT 1 FROM (SELECT * FROM (SELECT "p_partkey" AS "part.p_partkey", "p_name" AS "part.p_name", "p_mfgr" AS "part.p_mfgr", "p_brand" AS "part.p_brand", "p_type" AS "part.p_type", "p_size" AS "part.p_size", "p_container" AS "part.p_container", "p_retailprice" AS "part.p_retailprice", "p_comment" AS "part.p_comment" FROM part) AS "_t1" WHERE (("part.p_name" < 'foresu')) AND (("part.p_name" >= 'forest'))) AS "_t2" WHERE (("part.p_partkey" = "partsupp.ps_partkey")))) AS "_t3")) AS value, NULL AS of;
